// Physics trajectory simulator for realistic bouncy collision landing
const calculateRealisticBounceY = (
  relativeFrame: number,
  fallDuration: number,
  startY: number,
  endY: number,
  bounceDampening: number = 0.45,
  bounces: number = 3
) => {
  if (relativeFrame < 0) return startY;
  if (relativeFrame < fallDuration) {
    // Stage 1: Gravity-driven physical free fall (y = 0.5 * g * t^2)
    const progress = relativeFrame / fallDuration;
    const tSquare = progress * progress;
    return startY + (endY - startY) * tSquare;
  }

  // Stage 2: Inelastic dynamic bouncing
  const bounceFrame = relativeFrame - fallDuration;
  let currentY = endY;
  let gravity = 1.4; 
  let currentVelocity = fallDuration * 0.95 * bounceDampening; 
  let accumTime = 0;

  for (let b = 0; b < bounces; b++) {
    // Duration of this bounce cycle based on kinetic energy
    const bounceDuration = Math.max(2, Math.round(currentVelocity * 4.5));
    if (bounceFrame >= accumTime && bounceFrame < accumTime + bounceDuration) {
      const localT = bounceFrame - accumTime;
      const peakTime = bounceDuration / 2;
      // Parabolic arc for bounce motion
      const height = (currentVelocity * peakTime) - (0.5 * gravity * peakTime * peakTime);
      const instantHeight = (currentVelocity * localT) - (0.5 * gravity * localT * localT);
      if (instantHeight > 0) {
        currentY = endY - instantHeight;
      }
      break;
    }
    accumTime += bounceDuration;
    currentVelocity *= bounceDampening; // Energy absorption coefficient
  }
  return currentY;
};

// Squish & Stretch deformation scaling calculation based on velocity & collision impact
const calculateSquishStretch = (relativeFrame: number, fallDuration: number) => {
  if (relativeFrame < 0) return { sx: 1, sy: 1 };
  if (relativeFrame < fallDuration) {
    // Aerodynamic stretch during high speed drop
    const t = relativeFrame / fallDuration;
    const stretchFactor = interpolate(t, [0, 1], [0, 0.08]);
    return { sx: 1 - stretchFactor, sy: 1 + stretchFactor };
  }
  
  // Instant impact squish & ripple vibration dampening
  const bounceTime = relativeFrame - fallDuration;
  const vibration = Math.sin(bounceTime * 0.7) * Math.exp(-bounceTime * 0.15) * 0.22;
  return { sx: 1 + vibration, sy: 1 - vibration };
};

// Physics rotational swing wobble simulator
const calculatePhysicsWobbleAngle = (relativeFrame: number, fallDuration: number) => {
  if (relativeFrame < fallDuration) return 0;
  const bounceTime = relativeFrame - fallDuration;
  // Dynamic sine wave angular wobble decaying exponentially
  return Math.sin(bounceTime * 0.45) * Math.exp(-bounceTime * 0.08) * 12; // max tilt degrees
};

const CoffeeCupsDrop: React.FC<CoffeeCupsDropProps> = ({
  backgroundColor = "#F9F6F0",
  transparentBackground = true,
  durationInSeconds = 10,
  cupColor1 = "#D96B43",
  cupColor2 = "#4A7C59",
  cupColor3 = "#6883BA",
  lidColor = "#FFFFFF",
  sleeveColor = "#D2B48C",
  holderColor = "#C3A37A",
  titleText = "Fresh Brew To-Go",
  subtitleText = "3 Cups Ready • One Spot Left!",
  accentColor = "#2F3E46",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Conveyor phase transition length
  const conveyorDuration = 120;
  
  // Holder drop transition triggers after scroll phase
  const holderDelay = conveyorDuration;
  const holderSpring = spring({
    frame: frame - holderDelay,
    fps,
    config: { damping: 13, mass: 1 },
  });

  // Spatial references
  const baseCupHeight = height * 0.14;
  const trayCenterY = height * 0.55;
  const trayCenterX = width * 0.5;
  const isometricScale = Math.min(width, height) * 0.0028;

  // Destination spots within isometric matrix space
  const spot1X = trayCenterX + (-60 * isometricScale);
  const spot1Y = trayCenterY + (0 * isometricScale);

  const spot2X = trayCenterX + (0 * isometricScale);
  const spot2Y = trayCenterY + (-25 * isometricScale);

  const spot3X = trayCenterX + (60 * isometricScale);
  const spot3Y = trayCenterY + (0 * isometricScale);

  // Fall mechanics
  const dropHeightOffset = height * 0.6; // Launch height
  const fallDuration = 18; // Frames in physical descent

  // Cup 1 Drop Kinetics
  const c1Delay = holderDelay + 20;
  const c1Frame = frame - c1Delay;
  const cup1Y = calculateRealisticBounceY(c1Frame, fallDuration, spot1Y - dropHeightOffset, spot1Y);
  const cup1Scale = calculateSquishStretch(c1Frame, fallDuration);
  const cup1Rot = calculatePhysicsWobbleAngle(c1Frame, fallDuration);

  // Cup 2 Drop Kinetics
  const c2Delay = holderDelay + 33;
  const c2Frame = frame - c2Delay;
  const cup2Y = calculateRealisticBounceY(c2Frame, fallDuration, spot2Y - dropHeightOffset, spot2Y);
  const cup2Scale = calculateSquishStretch(c2Frame, fallDuration);
  const cup2Rot = calculatePhysicsWobbleAngle(c2Frame, fallDuration);

  // Cup 3 Drop Kinetics
  const c3Delay = holderDelay + 46;
  const c3Frame = frame - c3Delay;
  const cup3Y = calculateRealisticBounceY(c3Frame, fallDuration, spot3Y - dropHeightOffset, spot3Y);
  const cup3Scale = calculateSquishStretch(c3Frame, fallDuration);
  const cup3Rot = calculatePhysicsWobbleAngle(c3Frame, fallDuration);

  // Camera layout scale zoom sequence 
  const endHighlightStartFrame = holderDelay + 90;
  const zoomSpring = spring({
    frame: frame - endHighlightStartFrame,
    fps,
    config: { damping: 12, mass: 0.9 },
  });

  // Conveyor configuration
  const conveyorY = height * 0.42;
  const cupSpacing = baseCupHeight * 1.1; 
  const totalConveyorCups = 20;
  
  const scrollOffset = interpolate(
    frame,
    [0, conveyorDuration],
    [width + 100, -totalConveyorCups * cupSpacing],
    { extrapolateRight: "clamp" }
  );

  // Dynamic Holder movement logic
  const holderY = interpolate(
    holderSpring,
    [0, 1],
    [-height * 0.5, trayCenterY - (100 * isometricScale)],
    { extrapolateLeft: "clamp" }
  );

  const sceneScale = interpolate(zoomSpring, [0, 1], [1, 1.25], { extrapolateRight: "clamp" });
  const sceneTranslateY = interpolate(zoomSpring, [0, 1], [0, -height * 0.04], { extrapolateRight: "clamp" });

  const spotsOccupied: [boolean, boolean, boolean, boolean] = [
    c1Frame > fallDuration,
    c2Frame > fallDuration,
    c3Frame > fallDuration,
    false,
  ];

  const colorCycle = [cupColor1, cupColor2, cupColor3];

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none", overflow: "hidden" }}>
      <div
        style={{
          width: "100%",
          height: "100%",
          position: "relative",
          transform: `scale(${sceneScale}) translateY(${sceneTranslateY}px)`,
          transformOrigin: "center center",
          transition: "none",
        }}
      >
        {/* Conveyor line */}
        {frame < conveyorDuration + 20 && (
          <div
            style={{
              position: "absolute",
              top: conveyorY - (baseCupHeight * 0.9),
              left: scrollOffset,
              display: "flex",
              flexDirection: "row",
              gap: `${cupSpacing - (baseCupHeight * 0.75)}px`,
              transition: "none",
              pointerEvents: "none",
            }}
          >
            {Array.from({ length: totalConveyorCups }).map((_, index) => {
              const cupColor = colorCycle[index % colorCycle.length];
              return (
                <div key={index} style={{ transition: "none" }}>
                  <CupSVG
                    cupColor={cupColor}
                    lidColor={lidColor}
                    sleeveColor={sleeveColor}
                    height={baseCupHeight}
                  />
                </div>
              );
            })}
          </div>
        )}

        {/* Cardboard Holder */}
        <div
          style={{
            position: "absolute",
            left: trayCenterX - (150 * isometricScale),
            top: holderY,
            width: 300 * isometricScale,
            height: 200 * isometricScale,
            transformOrigin: "center center",
            transition: "none",
          }}
        >
          <IsometricHolderSVG holderColor={holderColor} spotsOccupied={spotsOccupied} />
        </div>

        {/* Cup 1 (Physics Drop) */}
        {frame > c1Delay && (
          <div
            style={{
              position: "absolute",
              left: spot1X - (baseCupHeight * 0.75 * 0.5),
              top: cup1Y - (baseCupHeight * 0.9),
              transform: `scale(${cup1Scale.sx}, ${cup1Scale.sy}) rotate(${cup1Rot}deg)`,
              transformOrigin: "bottom center",
              transition: "none",
              zIndex: cup1Y > trayCenterY ? 5 : 3,
            }}
          >
            <CupSVG
              cupColor={cupColor1}
              lidColor={lidColor}
              sleeveColor={sleeveColor}
              height={baseCupHeight}
            />
          </div>
        )}

        {/* Cup 2 (Physics Drop) */}
        {frame > c2Delay && (
          <div
            style={{
              position: "absolute",
              left: spot2X - (baseCupHeight * 0.75 * 0.5),
              top: cup2Y - (baseCupHeight * 0.9),
              transform: `scale(${cup2Scale.sx}, ${cup2Scale.sy}) rotate(${cup2Rot}deg)`,
              transformOrigin: "bottom center",
              transition: "none",
              zIndex: cup2Y > trayCenterY ? 5 : 3,
            }}
          >
            <CupSVG
              cupColor={cupColor2}
              lidColor={lidColor}
              sleeveColor={sleeveColor}
              height={baseCupHeight}
            />
          </div>
        )}

        {/* Cup 3 (Physics Drop) */}
        {frame > c3Delay && (
          <div
            style={{
              position: "absolute",
              left: spot3X - (baseCupHeight * 0.75 * 0.5),
              top: cup3Y - (baseCupHeight * 0.9),
              transform: `scale(${cup3Scale.sx}, ${cup3Scale.sy}) rotate(${cup3Rot}deg)`,
              transformOrigin: "bottom center",
              transition: "none",
              zIndex: cup3Y > trayCenterY ? 5 : 3,
            }}
          >
            <CupSVG
              cupColor={cupColor3}
              lidColor={lidColor}
              sleeveColor={sleeveColor}
              height={baseCupHeight}
            />
          </div>
        )}
      </div>
    </AbsoluteFill>
  );
};

export default CoffeeCupsDrop;